   "precollect": "全額預收",
   "detail": "旭然國際股份有限公司股票(代號：4556)最近30個營業日內曾發布處置，又因連續3個營業日達本中心作業要點第四條第一項第一款經本中心公布注意交易資訊，爰自115年8月4日起10個營業日(115年8月4日至115年8月17日，如遇休市、有價證券停止買賣、全日暫停交易則順延執行)改以人工管制之撮合終端機執行撮合作業(約每20分鐘撮合一次)，各證券商於投資人每日委託買賣該有價證券，應就其當日已委託之買賣，向該投資人收取全部之買進價金或賣出證券。信用交易部分，則收足融資自備款或融券保證金。但信用交易了結及違約專戶委託買賣該有價證券時，不在此限。惟若處置期間屆115年8月10日本中心作業要點第六條第二至第四項新規定實施日，修正其處置至115年8月10日止(如遇休市、有價證券停止買賣、全日暫停交易則順延執行)，並自115年8月10日起調整其人工管制之撮合終端機執行撮合作業(改以約每2分鐘撮合一次)。",
   "ruleNote": "8/10新制：10天→5天",
